-- ============================================================================
-- V29__sprint1_real_dev_seed_round2.sql
--
-- Round 2 of real DEV seed import — populates 5 Sprint 1 migrated tables that
-- were empty locally but had real DEV rows for tenant VN_VNM0004_000001.
--
-- Identified by the parity audit at docs/refactor-wecms/db-parity-audit-2026-04-30.md
-- All real DEV rows. Real PKs preserved. INSERT ... ON CONFLICT DO NOTHING.
--
-- Tables seeded:
--   bat_call_his              84 rows  (DEV had 84 for tenant)
--   busa_doc_rcv_pay_his      26 rows  (DEV had 26 for tenant)
--   einv_fee_detl             16 rows  (DEV had 16 for tenant)
--   einv_tax_detl             50 rows  (DEV has 669 — sampled 50 most recent)
--   ext_tran_call_his         50 rows  (DEV has 24K — sampled 50 most recent;
--                                       table is global-scoped, not tenant-filtered)
--
-- Note: ext_tran_call_his rows include some with biz_key=NULL (DEV behaviour for
-- batch system calls) and some with the tenant's biz_key. Both kept verbatim.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. BAT_CALL_HIS — 84 rows
-- ----------------------------------------------------------------------------
ON CONFLICT (job_id, biz_key, job_date, job_str_tm, req_date, mod_uid) DO NOTHING;

-- ----------------------------------------------------------------------------
-- 2. BUSA_DOC_RCV_PAY_HIS — 26 rows
-- Local has 4 extra columns (seq_no, acct_seq_no, rcv_pay_dt, amt) which are
-- left NULL by this insert; they're convenience columns not in DEV.
-- Local PK is (biz_key, doc_id, seq_no) — seq_no NULL means rows still insert
-- because we need to make seq_no non-NULL. Use rcv_pay_his_seq_no as seq_no.
-- ----------------------------------------------------------------------------
ON CONFLICT (biz_key, doc_id, seq_no) DO NOTHING;

-- ----------------------------------------------------------------------------
-- 3. EINV_FEE_DETL — 16 rows
-- ----------------------------------------------------------------------------
ON CONFLICT (biz_key, doc_id, disp_ord) DO NOTHING;

-- ----------------------------------------------------------------------------
-- 4. EINV_TAX_DETL — 50 rows (sampled most-recent 50 of 669 DEV rows)
-- ----------------------------------------------------------------------------
ON CONFLICT (biz_key, doc_id, disp_ord) DO NOTHING;

-- ----------------------------------------------------------------------------
-- 5. EXT_TRAN_CALL_HIS — 50 rows (sampled most-recent 50 of 24K DEV rows)
-- ----------------------------------------------------------------------------
ON CONFLICT (svc_id, ref_date, seq_no) DO NOTHING;
